#include <iostream>
#include <limits>

int readIntInRange(int low, int high)
{
    while (true)
    {
        int value{};
        std::cin >> value;
        if (!std::cin)
        {
            std::cin.clear();
            std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
            continue;
        }
        if (value >= low && value <= high)
        {
            return value;
        }
    }
}
